package com.msarobotika.cyberdeck
import org.junit.Assert.*
import org.junit.Test
class AgentConversationPolicyTest {
 private fun done(id:String="1"):AgentSession {val plan=AgentPlan(listOf(AgentTool.CONNECTION));val steps=listOf(AgentStepResult(AgentTool.CONNECTION,result=DiagnosticResult("connection","own","now","Native observation",emptyList())));return AgentSession(request="Own request",plan=plan,results=steps,run=AgentRun(plan,id,"end",steps))}
 @Test fun historyIsBoundedAndAnUpdatedRunReplacesRatherThanDuplicates(){var rows=emptyList<AgentExchange>();for(i in 1..8)rows=AgentConversationPolicy.record(rows,done(i.toString()));assertEquals(5,rows.size);assertEquals("8",rows.first().id);val updated=AgentConversationPolicy.record(rows,done("8").copy(request="Updated"));assertEquals(5,updated.size);assertEquals("Updated",updated.first().request)}
 @Test fun runningOrUnexecutedPlansNeverBecomeRecordedConversations(){assertTrue(AgentConversationPolicy.record(emptyList(),done().copy(running=true)).isEmpty());assertTrue(AgentConversationPolicy.record(emptyList(),AgentSession(plan=done().plan)).isEmpty())}
 @Test fun generatedAndManualTextAreNotPromotedToNativeAnswers(){val plan=AgentPlan(listOf(AgentTool.ANALYST));val steps=listOf(AgentStepResult(AgentTool.ANALYST,result=DiagnosticResult("ai","own","now","UNTRUSTED GENERATED",emptyList())));val row=AgentConversationPolicy.record(emptyList(),AgentSession(plan=plan,results=steps,run=AgentRun(plan,"1","2",steps))).single();assertFalse(row.answer.contains("UNTRUSTED"));assertEquals("Revisión finalizada",row.status)}
 @Test fun voiceRequiresOptInForegroundReadyAndANewCompletion(){val s=done();assertTrue(AgentConversationPolicy.shouldSpeak(s,true,true,true,""));assertFalse(AgentConversationPolicy.shouldSpeak(s,false,true,true,""));assertFalse(AgentConversationPolicy.shouldSpeak(s,true,false,true,""));assertFalse(AgentConversationPolicy.shouldSpeak(s,true,true,false,""));assertFalse(AgentConversationPolicy.shouldSpeak(s,true,true,true,"1"))}
 @Test fun voiceDoesNotTreatErrorsWaitingOrCancellationAsACompletedReply(){val s=done();for(step in listOf(s.results.single().copy(awaiting=true),s.results.single().copy(error="error"))){assertFalse(AgentConversationPolicy.shouldSpeak(s.copy(run=s.run!!.copy(steps=listOf(step))),true,true,true,""))};assertFalse(AgentConversationPolicy.shouldSpeak(s.copy(running=true),true,true,true,""));assertFalse(AgentConversationPolicy.shouldSpeak(s.copy(notice="Stopped"),true,true,true,""))}
}
